#include <iostream>
using namespace std;

int power(int base, int exp = 2) {
    int result = 1;
    for (int i = 0; i < exp; i++) {
        result *= base;
    }
    return result;
}

int main() {
    cout << power(5) << endl;
    cout << power(2, 10) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int area(int side) { return side * side; }
int area(int w, int h) { return w * h; }
double area(double radius) { return 3.14 * radius * radius; }

int main() {
    cout << area(5) << endl;
    cout << area(4, 6) << endl;
    cout << area(2.0) << endl;
    return 0;
}

